using Microsoft.AspNetCore.Mvc; using RaceDay.Web.Models; using RaceDay.Web.Services;
namespace RaceDay.Web.Controllers;
public class AccountController(ApiClient api):Controller{[HttpGet]public IActionResult Login(string? returnUrl=null)=>View(new LoginModel("",""));[HttpPost]public async Task<IActionResult> Login(LoginModel m,string? returnUrl=null){if(!ModelState.IsValid)return View(m);var u=await api.Login(m);if(u is null){ModelState.AddModelError("","Email or password is incorrect.");return View(m);}api.SetUser(u);return Redirect(returnUrl??(u.Role==UserRole.Organiser?"/Organiser":"/Participant"));}[HttpGet]public IActionResult Register()=>View(new RegisterModel("","","",UserRole.Participant,null));[HttpPost]public async Task<IActionResult> Register(RegisterModel m){if(!ModelState.IsValid)return View(m);var u=await api.Register(m);if(u is null){ModelState.AddModelError("","Registration failed. Check the email is not already registered.");return View(m);}api.SetUser(u);return Redirect(u.Role==UserRole.Organiser?"/Organiser":"/Participant");}[HttpPost]public async Task<IActionResult> Logout(){await api.Logout();return RedirectToAction("Index","Home");}}
